                    result = self.handle_initialize(params)
                elif not self.initialized:
                    # F-004 (A-012): strict MCP ordering — nothing but
                    # initialize may be served before the handshake completes.
                    raise MCPError(
                        -32002,
                        "Server not initialized: call initialize before "
                        "tools/list, tools/call or ping",
                    )
                elif method == "tools/list":
                    result = self.handle_tools_list()
                elif method == "tools/call":
                    result = self.handle_tools_call(params)
                elif method == "ping":
                    result = self.handle_ping()
                elif method == "notifications/initialized":
                    result = {}
                else:
                    raise MCPError(-32601, f"Method not found: {method}")
            except MCPError as error:
                self._write(
                    {
                        "jsonrpc": "2.0",
                        "id": request_id,
                        "error": {"code": error.code, "message": error.message},
                    }
                )
                continue

            self._write({"jsonrpc": "2.0", "id": request_id, "result": result})


def _sha256_hex(value: bytes) -> str:
    from hashlib import sha256

    return sha256(value).hexdigest()


def _ledger_targets(name: str) -> list[str]:
    return list(LEDGER_TARGETS.get(name, []))


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--repo-root",
        type=Path,
        default=None,
        help="Repository root used to locate thin prompt assets (default: cwd).",
    )
    parser.add_argument(
        "--version",
        action="version",
        version=f"{SERVER_NAME} {__version__}",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    # MCP stdio is a UTF-8 JSON-RPC transport regardless of the host locale.
    # Windows otherwise inherits a legacy console code page for redirected
    # pipes, corrupting non-ASCII tool descriptions before clients decode them.
    if hasattr(sys.stdin, "reconfigure"):
        sys.stdin.reconfigure(encoding="utf-8", errors="strict")
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="strict")
    args = build_parser().parse_args(argv)
    return MCPServer(repo_root=args.repo_root).serve()


if __name__ == "__main__":
    raise SystemExit(main())

